def unpack(destination):
 destination=Path(destination).resolve();destination.mkdir(parents=True,exist_ok=True)
 blob=base64.b85decode(PAYLOAD);assert hashlib.sha256(blob).hexdigest()==PAYLOAD_SHA256
 with tarfile.open(fileobj=io.BytesIO(gzip.decompress(blob)),mode='r:') as tar:
  members=tar.getmembers();assert len(members)==len(SOURCE_MANIFEST)
  assert {m.name for m in members}==set(SOURCE_MANIFEST)
  for member in members:
   path=Path(member.name);assert member.isfile() and not path.is_absolute() and '..' not in path.parts
   target=destination/path;assert target.resolve().is_relative_to(destination) and not target.is_symlink()
   data=tar.extractfile(member).read();assert hashlib.sha256(data).hexdigest()==SOURCE_MANIFEST[member.name]
   target.parent.mkdir(parents=True,exist_ok=True);assert not target.exists() or hashlib.sha256(target.read_bytes()).hexdigest()==SOURCE_MANIFEST[member.name],'Refusing to replace modified extracted source';target.write_bytes(data)
 return destination
def main():
 if sys.flags.optimize:raise RuntimeError("Proof launcher requires Python assertions enabled")
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--plan',action='store_true');p.add_argument('--self-test',action='store_true');p.add_argument('--prepare',action='store_true');p.add_argument('--execute-browser',action='store_true');p.add_argument('--cache',type=Path,default=Path('actual-operator-cache'));p.add_argument('--private',type=Path,default=Path('actual-operator-output'));p.add_argument('--extract-only',action='store_true');p.add_argument('--validate-report',type=Path);p.add_argument('--validate-public-build',type=Path);p.add_argument('--render-report',type=Path);p.add_argument('--build-proof',type=Path);p.add_argument('--html-output',type=Path);a=p.parse_args()
 root=unpack(a.private/('source-'+PAYLOAD_SHA256[:12]));env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1')
 def run(*args):subprocess.run([sys.executable,*map(str,args)],cwd=root,env=env,check=True)
 if a.extract_only:print(json.dumps({'payload_sha256':PAYLOAD_SHA256,'files':len(SOURCE_MANIFEST)}));return
 if a.render_report:
  if a.html_output is None:raise ValueError('--html-output is required with --render-report')
  extra=['--build-proof',a.build_proof.resolve()] if a.build_proof else []
  run('tools/render_report.py','--report',a.render_report.resolve(),'--output',a.html_output.resolve(),*extra);return
 if a.validate_report:run('browser/browser.py','--validate-report',a.validate_report.resolve());return
 if a.validate_public_build:run('tools/public_build_receipt.py','--validate',a.validate_public_build.resolve());return
 run('tools/bootstrap.py','--verify-vendor')
 if a.self_test:
  run('-m','unittest','discover','-s','workflow','-p','test_*.py','-v');run('-m','unittest','discover','-s','browser/tests','-p','test_*.py','-v');run('-m','unittest','discover','-s','tests','-p','test_*.py','-v')
 if not(a.prepare or a.execute_browser):
  run('tools/bootstrap.py','--plan');run('browser/browser.py','--plan');return
 # Never let a failed new attempt validate/upload an older scalar receipt.
 for stale in (a.private/'public-build.json',a.private/'browser/browser-report.json',a.private/'report.html'):
  if stale.is_symlink():raise ValueError('Refusing symlink receipt target')
  stale.unlink(missing_ok=True)
 paths=root/'build/toolchain-paths.json';run('tools/bootstrap.py','--cache',a.cache.resolve(),'--output',paths)
 run('tools/build.py','--paths',paths);run('tools/inspect_wasm.py','--paths',paths)
 run('tools/public_build_receipt.py','--output',a.private.resolve()/'public-build.json')
 run('browser/browser.py','--manifest',root/'evidence/build.json','--verify-inputs')
 if a.execute_browser:run('browser/browser.py','--manifest',root/'evidence/build.json','--private',a.private.resolve()/'browser','--execute')
if __name__=='__main__':main()
